import re,glob,collections
c=collections.Counter();blank=[]
for f in sorted(glob.glob('*.txt')):
    t=open(f).read()
    for p in re.split(r'=== page \d+',t):
        if 'finds the following' in p:
            m=re.search(r'violation\(s\):(.*?)(?:recommends|$)',p,re.S)
            s=m.group(1)
            m2=re.search(r'8-1-26-\s*(\S+)',s)
            if m2: c[m2.group(1)]+=1
            else: c['BLANK']+=1; blank.append(f)
for k,v in sorted(c.items()): print(repr(k),v)
print(collections.Counter(blank))
